/* @author MILO-GAO(高振銘)@2020 */ package page2020.anno;import java.lang.reflect.Field;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.core.App;import page2020.core.Log;import page2020.util.EmptyUtil;public class FormProp extends DataProp<FormProp, CtrlItem> {	private static Logger log = LoggerFactory.getLogger(FormProp.class);	private Form2020 anno;	public FormProp(Class<?> clazz, String alias) {		super(clazz);		Form2020 anno = null;		String topClassName = null;		if (clazz.isAnnotationPresent(Form2020.class)) {			anno = clazz.getAnnotation(Form2020.class);			topClassName = EmptyUtil.not(alias) ? alias : anno.name();			super.base(topClassName);			this.anno = anno;			if (Log.anno) {				log.info(this.toString());			}		} else {			log.error("FormProp: '" + clazz.getCanonicalName() + "' is NOT Form2020 annotation !");			return;		}		Class<?> superClazz = clazz;		do {			String annoClassName = null;			if (superClazz.isAnnotationPresent(Form2020.class)) {				annoClassName = superClazz.getAnnotation(Form2020.class).name();			}			if (EmptyUtil.is(annoClassName)) {				annoClassName = App.className(superClazz);			}					Field[] fields = superClazz.getDeclaredFields();			for (int i=0; i < fields.length; i++) {				super.cache(new CtrlItem(fields[i], annoClassName, topClassName));			}							super.storage();			superClazz = superClazz.getSuperclass();		} while (! superClazz.equals(Object.class));		super.sorting();		if (Log.anno) {			log.info(this.toString());			int count = super.count();			for (int i=0; i < count; i++) {				log.info("[" + i + "] " + super.value(i).toString());			}		}	}	@Override	public String toString() {		return "FormProp [getDataKeys()=" + getDataKeys() + ", getDisplayNames()=" + getDisplayNames() + "]";	}	public Form2020 getAnno() {		return anno;	}	public void setAnno(Form2020 anno) {		this.anno = anno;	}}